const QUOTE_API='https://doc-freela-aprovar.vendr2017.chatgpt.site';
const quoteDefaultBrand={logo:'',favicon:'',primary:'#ff633a',secondary:'#e53943',intro:'Obrigado pelo seu interesse. Preparamos esta proposta especialmente para o seu negócio.',footer:'DOCTYPE Marketing & Tecnologia',thanks:'Obrigado pela parceria. Entraremos em contato em breve!',agencyName:'',tagline:'',about:'',methodology:'',portfolio:'',contactEmail:'',contactPhone:'',website:'',headline:'',welcome:'',approvalLabel:'',showReviews:false,reviews:[],showProjects:false,maxProjects:4,projects:[]};
const quoteDefaultPdf={template:'moderno',primary:'#111111',accent:'#ff633a',background:'#ffffff',text:'#1a1a1a',logo:'',banner:'',watermark:'CONFIDENCIAL',opacity:8,intro:'Obrigado pelo interesse em nossa proposta.',terms:'',footer:'DOCTYPE Marketing & Tecnologia',blocks:{logo:true,description:true,validity:true,delivery:true,payment:true,contact:true},models:[{id:'default',title:'Termos e Condições Gerais',body:'Ao aprovar esta proposta, as partes concordam com os serviços, valores e condições apresentados.',default:true}]};
function quoteLoad(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
const quoteState={items:quoteLoad('docfreela-quotes-v1',[]),contracts:quoteLoad('docfreela-contracts-v1',[]),brand:{...quoteDefaultBrand,...quoteLoad('docfreela-quote-brand-v1',{})},pdf:{...quoteDefaultPdf,...quoteLoad('docfreela-quote-pdf-v1',{})},tab:'Orçamentos',query:'',status:'Todos',archived:false,dialog:null,menuId:null,editingId:null,previewId:null};
const quotePersist=()=>{localStorage.setItem('docfreela-quotes-v1',JSON.stringify(quoteState.items));localStorage.setItem('docfreela-contracts-v1',JSON.stringify(quoteState.contracts));localStorage.setItem('docfreela-quote-brand-v1',JSON.stringify(quoteState.brand));localStorage.setItem('docfreela-quote-pdf-v1',JSON.stringify(quoteState.pdf))};
const quoteToday=()=>new Date().toISOString().slice(0,10);
const quoteTotal=q=>Math.max(0,(q.items||[]).reduce((n,x)=>n+(Number(x.quantity)||0)*(Number(x.price)||0),0)-(Number(q.discount)||0));
const quoteClient=q=>clientsState.items.find(c=>c.id===q.clientId);
const quoteLink=q=>q.remoteId?`${QUOTE_API}/p/${q.remoteId}`:'';
const quoteHex=(x,defaultValue)=>/^#[0-9a-fA-F]{6}$/.test(x||'')?x:defaultValue;
function quoteTrack(q,event){if(typeof dashActivity==='function')dashActivity(event+': '+q.title,q.clientId)}
function quoteSyncClient(q){const c=quoteClient(q);if(!c)return;if(q.charge){c.receivables=c.receivables||[];if(!c.receivables.some(x=>x.id===q.charge.id))c.receivables.push(q.charge)}c.quotes=c.quotes||[];const existing=c.quotes.find(x=>x.id===q.id);if(existing)Object.assign(existing,{status:q.status,title:q.title,amount:quoteTotal(q),number:q.number});else c.quotes.push({id:q.id,status:q.status,title:q.title,amount:quoteTotal(q),number:q.number})}
async function quoteRemote(q){const payload={number:q.number,title:q.title,clientName:q.clientName,clientEmail:q.clientEmail,description:q.description,payment:q.payment,delivery:q.delivery,terms:q.terms,validity:q.validity,issued:q.issued,discount:q.discount,items:q.items,branding:quoteState.brand};const editToken=q.editToken||crypto.randomUUID()+crypto.randomUUID();const isEdit=!!q.remoteId;const response=await fetch(`${QUOTE_API}/api/quotes${isEdit?'/'+q.remoteId:''}`,{method:isEdit?'PUT':'POST',headers:{'content-type':'application/json',...(isEdit?{'x-edit-token':editToken}:{})},body:JSON.stringify(isEdit?{quote:payload}:{quote:payload,editToken})});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível gerar o link.');q.remoteId=data.id;q.editToken=editToken;q.remoteStatus=data.status;quotePersist();return data}
async function quoteRefresh(){const items=quoteState.items.filter(q=>q.remoteId);await Promise.all(items.map(async q=>{try{const r=await fetch(`${QUOTE_API}/api/quotes/${q.remoteId}`);if(!r.ok)return;const data=await r.json();if(data.status==='aprovado'&&q.status!=='aprovado'){q.status='aprovado';q.approvedAt=data.approvedAt;q.approverName=data.approverName;q.approverEmail=data.approverEmail;quoteTrack(q,'Proposta aprovada pelo cliente')}quoteSyncClient(q)}catch{}}));quotePersist();if(document.querySelector('.workspace.quotes-mode')&&quoteState.tab==='Orçamentos')renderQuotes()}
const quoteTabs=['Orçamentos','Contratos','Página de Aprovação','PDF'];
function renderQuotes(){const w=document.querySelector('.workspace');w.className='workspace quotes-mode';document.querySelector('#page-title').textContent='Orçamentos';w.innerHTML=`<div class="quote-shell"><header class="quote-head"><h2>Gestão de Orçamentos</h2><p>Gerencie todos os seus orçamentos em um só lugar</p><div class="quote-actions"><button data-quote="tab" data-tab="Contratos">⚙ Contrato</button><button data-quote="new-contract">＋ Novo contrato</button><button class="primary" data-quote="new">＋ Novo Orçamento</button></div></header><nav class="quote-tabs" aria-label="Seções de orçamentos">${quoteTabs.map(t=>`<button data-quote="tab" data-tab="${t}" class="${quoteState.tab===t?'active':''}">${{Orçamentos:'▤ ',Contratos:'▣ ','Página de Aprovação':'',PDF:'⇩ '}[t]}${t}</button>`).join('')}</nav><div id="quote-content">${quoteState.tab==='Orçamentos'?quoteList():quoteState.tab==='Contratos'?quoteContracts():quoteState.tab==='Página de Aprovação'?quoteBranding():quotePdfSettings()}</div></div>`}
function quoteRows(){return quoteState.items.filter(q=>(quoteState.archived||!q.archived)&&(quoteState.status==='Todos'||q.status===quoteState.status)&&[q.number,q.title,q.clientName].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(quoteState.query.toLocaleLowerCase('pt-BR'))))}
function quoteList(){const active=quoteState.items.filter(q=>!q.archived),rows=quoteRows();return `<div class="quote-stats"><div>Rascunhos<strong>${active.filter(q=>q.status==='rascunho').length}</strong></div><div>Enviados<strong>${active.filter(q=>q.status==='enviado').length}</strong></div><div>Aprovados<strong class="green">${active.filter(q=>q.status==='aprovado').length}</strong></div><div>Valor Total Aprovado<strong class="green">${money(active.filter(q=>q.status==='aprovado').reduce((n,q)=>n+quoteTotal(q),0))}</strong></div></div><div class="quote-filter-card"><input id="quote-search" type="search" placeholder="Buscar por título, número ou cliente..." value="${esc(quoteState.query)}"><select id="quote-status" aria-label="Filtrar status">${['Todos','rascunho','enviado','aprovado','recusado'].map(x=>`<option value="${x}" ${quoteState.status===x?'selected':''}>${x==='Todos'?'Todos':x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select><button data-quote="archived">▣ ${quoteState.archived?'Ocultar':'Mostrar'} Arquivados</button><button data-quote="refresh" title="Atualizar aprovações">↻ Atualizar</button></div><div class="quote-table-wrap"><table><thead><tr><th>Número</th><th>Título</th><th>Cliente</th><th>Valor</th><th>Status</th><th>Data</th><th>Validade</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(q=>`<tr><td>${esc(q.number)}</td><td><button class="quote-title" data-quote="preview" data-id="${esc(q.id)}">${esc(q.title)}</button></td><td>${esc(q.clientName)}<small>${esc(q.clientEmail)}</small></td><td><b>${money(quoteTotal(q))}</b></td><td><span class="quote-status ${esc(q.status)}">${esc(q.status)}</span></td><td>${formatDate(q.issued)}</td><td>${formatDate(q.validity)}</td><td class="quote-cell-actions"><button data-quote="pdf-preview" data-id="${esc(q.id)}" title="PDF" aria-label="PDF de ${esc(q.title)}">⇩</button><button data-quote="menu" data-id="${esc(q.id)}" aria-label="Ações de ${esc(q.title)}">⋮</button>${quoteState.menuId===q.id?quoteMenu(q):''}</td></tr>`).join(''):'<tr><td colspan="8" class="quote-empty">Nenhum orçamento encontrado. Crie um orçamento para começar.</td></tr>'}</tbody></table></div>`}
function quoteMenu(q){const actions=[['edit','▤ Editar'],['send','➤ Preparar e-mail'],['complete','✓ Concluir (sem email)'],['approve','◉ Aprovar Manualmente'],['charge','＄ Gerar cobrança'],['details','ⓘ Ver Detalhes'],['preview','◎ Visualizar'],['copy','▢ Copiar Link'],['share','♧ Compartilhar'],['email','✉ Enviar por Email'],['pdf-email','⇩ Preparar e-mail com PDF'],['duplicate','▢ Duplicar'],['contract','▣ Gerar Contrato'],['archive','▣ '+(q.archived?'Restaurar':'Arquivar')],['delete','♜ Excluir']];return `<div class="quote-menu">${actions.map(([a,label])=>`<button data-quote="${a}" data-id="${esc(q.id)}">${label}</button>`).join('')}</div>`}
function quoteContracts(){return `<section class="quote-panel"><h3>▣ Contratos Gerados</h3>${quoteState.contracts.length?`<div class="quote-table-wrap"><table><thead><tr><th>Cliente</th><th>Projeto</th><th>Valor</th><th>Status</th><th>Data</th><th>Ações</th></tr></thead><tbody>${quoteState.contracts.map(c=>`<tr><td>${esc(c.clientName)}</td><td>${esc(c.title)}</td><td>${money(c.amount)}</td><td><span class="quote-status ${esc(c.status)}">${esc(c.status)}</span></td><td>${formatDate(c.date)}</td><td><button data-quote="contract-preview" data-id="${esc(c.id)}">Visualizar</button><button data-quote="contract-delete" data-id="${esc(c.id)}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="quote-empty">Nenhum contrato gerado ainda.</div>'}</section>`}
const quotePalette=[['Doctype','#ff633a','#e53943'],['Sunset','#ff6b6b','#ffe66d'],['Ocean','#4ecdc4','#556270'],['Forest Dream','#52b788','#2d6a4f'],['Rose Gold','#ec4899','#f59e0b'],['Electric Blue','#3b82f6','#8b5cf6'],['Fire & Ice','#ef4444','#06b6d4']];
function quoteBranding(){const b=quoteState.brand,q=quoteState.items.find(x=>x.id===quoteState.previewId)||quoteState.items[0];return `<div class="quote-config-layout"><div class="quote-config"><section class="quote-panel"><h3>◉ Logo e Cores</h3><label>Logo da Página de Orçamento <small>(opcional)</small></label><div class="quote-upload-preview">${b.logo?`<img src="${esc(b.logo)}" alt="Logo da página de orçamento">`:'Sem logo cadastrado'}</div><label class="quote-upload-button">↑ Enviar logo (PNG/JPG)<input type="file" data-quote-upload="logo" accept="image/png,image/jpeg,image/webp" hidden></label>${b.logo?'<button data-quote="remove-logo">Remover logo</button>':''}<label>Favicon da página <small>(opcional)</small></label><div class="quote-upload-preview compact">${b.favicon?`<img src="${b.favicon}" alt="Favicon">`:'Sem favicon'}</div><label class="quote-upload-button">↑ Enviar favicon<input type="file" data-quote-upload="favicon" accept="image/png,image/jpeg,image/webp" hidden></label><hr><h4>Paletas de Cores</h4><div class="quote-palettes">${quotePalette.map(([name,p,s])=>`<button data-quote="palette" data-primary="${p}" data-secondary="${s}"><span style="background:${p}"></span><span style="background:${s}"></span><b>${name}</b></button>`).join('')}</div><h4>Personalizar Cores</h4><div class="quote-two"><label>Cor Primária<input type="color" data-quote-brand="primary" value="${quoteHex(b.primary,'#ff633a')}"></label><label>Cor Secundária<input type="color" data-quote-brand="secondary" value="${quoteHex(b.secondary,'#e53943')}"></label></div></section><section class="quote-panel"><h3>Apresentação da agência</h3><p>Estas informações aparecem na página enviada ao cliente.</p><label>Nome da agência<input data-quote-brand="agencyName" maxlength="120" placeholder="Ex: Doctype Marketing & Tecnologia" value="${esc(b.agencyName)}"></label><label>Frase de apresentação<input data-quote-brand="tagline" maxlength="180" placeholder="O que sua agência entrega" value="${esc(b.tagline)}"></label><label>Sobre a agência<textarea data-quote-brand="about" rows="4" maxlength="2500" placeholder="Conte sua experiência e diferenciais">${esc(b.about)}</textarea></label><label>Como trabalhamos<textarea data-quote-brand="methodology" rows="4" maxlength="2500" placeholder="Explique seu processo e etapas">${esc(b.methodology)}</textarea></label><label>Portfólio ou resultados<textarea data-quote-brand="portfolio" rows="3" maxlength="2000" placeholder="Mostre trabalhos, cases ou resultados">${esc(b.portfolio)}</textarea></label><div class="quote-two"><label>E-mail comercial<input data-quote-brand="contactEmail" type="email" maxlength="160" value="${esc(b.contactEmail)}"></label><label>WhatsApp<input data-quote-brand="contactPhone" maxlength="80" value="${esc(b.contactPhone)}"></label></div><label>Site ou portfólio (URL)<input data-quote-brand="website" type="url" maxlength="300" placeholder="https://..." value="${esc(b.website)}"></label></section><section class="quote-panel quote-editor-panel"><details open><summary>Textos Personalizados</summary><div class="quote-editor-body"><label>Título Principal (opcional)<input data-quote-brand="headline" maxlength="180" placeholder="Se vazio, usa o título do orçamento" value="${esc(b.headline)}"></label><label>Mensagem de Boas-vindas (opcional)<textarea data-quote-brand="welcome" maxlength="1200" rows="3">${esc(b.welcome)}</textarea></label><label>Texto do Botão de Aprovação (opcional)<input data-quote-brand="approvalLabel" maxlength="70" placeholder="Padrão: Aprovar Proposta" value="${esc(b.approvalLabel)}"></label><label>Mensagem de Agradecimento (opcional)<textarea data-quote-brand="thanks" maxlength="500" rows="3">${esc(b.thanks)}</textarea></label></div></details></section><section class="quote-panel quote-editor-panel"><details><summary>Avaliações de Clientes</summary><div class="quote-editor-body"><label class="quote-toggle">Exibir Avaliações <input type="checkbox" data-quote-editor-toggle="showReviews" ${b.showReviews?'checked':''}></label><p>Mostra depoimentos reais de clientes na página de proposta.</p><div class="quote-editor-items">${(b.reviews||[]).map((x,i)=>quoteReviewEditor(x,i)).join('')}</div><button type="button" data-quote-editor-add="reviews">＋ Adicionar Avaliação</button></div></details></section><section class="quote-panel quote-editor-panel"><details><summary>Projetos do Portfólio</summary><div class="quote-editor-body"><label class="quote-toggle">Exibir Projetos <input type="checkbox" data-quote-editor-toggle="showProjects" ${b.showProjects?'checked':''}></label><label>Máximo de Projetos<input type="number" min="1" max="6" data-quote-editor-setting="maxProjects" value="${Math.min(6,Math.max(1,Number(b.maxProjects)||4))}"></label><div class="quote-editor-items">${(b.projects||[]).map((x,i)=>quoteProjectEditor(x,i)).join('')}</div><button type="button" data-quote-editor-add="projects">＋ Adicionar Projeto</button></div></details></section><section class="quote-panel"><h3>Introdução e Rodapé</h3><label>Introdução da proposta<textarea data-quote-brand="intro" rows="3">${esc(b.intro)}</textarea></label><label>Rodapé<input data-quote-brand="footer" value="${esc(b.footer)}"></label></section><section class="quote-panel"><button class="primary" data-quote="save-brand">Salvar aparência</button><p class="quote-muted">Selecione um orçamento e publique a apresentação no link do cliente.</p><label>Orçamento da apresentação<select id="quote-brand-preview-select"><option value="">Exemplo</option>${quoteState.items.filter(x=>!x.archived).map(x=>`<option value="${esc(x.id)}" ${quoteState.previewId===x.id?'selected':''}>${esc(x.title)} · ${esc(x.clientName)}</option>`).join('')}</select></label><button data-quote="publish-brand" ${q?'':'disabled'}>↗ Gerar / atualizar link</button>${q?.remoteId?`<a class="quote-public-link" href="${quoteLink(q)}" target="_blank" rel="noopener">Abrir página publicada ↗</a>`:''}</section></div><div class="quote-live"><p>PRÉVIA AO VIVO</p>${quoteWebPreview(q,b)}</div></div>`}
function quoteReviewEditor(x,i){return `<div class="quote-editor-item"><div class="quote-editor-item-head"><b>Avaliação ${i+1}</b><button type="button" data-quote-editor-remove="reviews" data-index="${i}">Remover</button></div><label>Nome do Cliente<input data-quote-editor-field="name" data-kind="reviews" data-index="${i}" maxlength="120" value="${esc(x.name)}"></label><label>Avaliação (1-5 estrelas)<input type="number" min="1" max="5" data-quote-editor-field="rating" data-kind="reviews" data-index="${i}" value="${Math.min(5,Math.max(1,Number(x.rating)||5))}"></label><label>Comentário<textarea data-quote-editor-field="comment" data-kind="reviews" data-index="${i}" maxlength="1000" rows="3">${esc(x.comment)}</textarea></label><label>Foto do Cliente (opcional)</label>${x.photo?`<img class="quote-editor-image" src="${esc(x.photo)}" alt="Foto de ${esc(x.name)}">`:''}<label class="quote-upload-button">↑ Enviar foto<input type="file" data-quote-editor-image="reviews" data-index="${i}" accept="image/png,image/jpeg,image/webp" hidden></label>${x.photo?`<button type="button" data-quote-editor-clear="reviews" data-index="${i}">Remover foto</button>`:''}</div>`}
function quoteProjectEditor(x,i){return `<div class="quote-editor-item"><div class="quote-editor-item-head"><b>Projeto ${i+1}</b><button type="button" data-quote-editor-remove="projects" data-index="${i}">Remover</button></div><label>Nome do projeto<input data-quote-editor-field="title" data-kind="projects" data-index="${i}" maxlength="160" value="${esc(x.title)}"></label><label>Cliente ou área<input data-quote-editor-field="client" data-kind="projects" data-index="${i}" maxlength="120" value="${esc(x.client)}"></label><label>Descrição do trabalho<textarea data-quote-editor-field="description" data-kind="projects" data-index="${i}" maxlength="1000" rows="3">${esc(x.description)}</textarea></label><label>Link do projeto (opcional)<input type="url" data-quote-editor-field="url" data-kind="projects" data-index="${i}" maxlength="300" placeholder="https://..." value="${esc(x.url)}"></label>${x.image?`<img class="quote-editor-image" src="${esc(x.image)}" alt="Imagem do projeto ${esc(x.title)}">`:''}<label class="quote-upload-button">↑ Enviar imagem<input type="file" data-quote-editor-image="projects" data-index="${i}" accept="image/png,image/jpeg,image/webp" hidden></label>${x.image?`<button type="button" data-quote-editor-clear="projects" data-index="${i}">Remover imagem</button>`:''}</div>`}
function quoteRefreshWebPreview(){const preview=document.querySelector('.quote-live .quote-web-preview');if(preview){const q=quoteState.items.find(q=>q.id===quoteState.previewId)||quoteState.items[0];preview.outerHTML=quoteWebPreview(q,quoteState.brand)}}
function quoteWebPreview(q,b){const demo=q||{number:'2026-001',title:'Proposta comercial',clientName:'Cliente Exemplo',description:'Descrição do projeto e serviços oferecidos.',items:[{name:'Serviço A',description:'Descrição do serviço',quantity:1,price:1500}],discount:0,payment:'A combinar'};return `<div class="quote-web-preview" style="--quote-a:${quoteHex(b.primary,'#ff633a')};--quote-b:${quoteHex(b.secondary,'#e53943')}">${b.logo?`<img class="quote-logo" src="${esc(b.logo)}" alt="Logo de ${esc(b.agencyName||'sua agência')}">`:'<span class="quote-circle">D</span>'}${b.agencyName?`<h3 class="quote-agency-name">${esc(b.agencyName)}</h3>`:''}${b.tagline?`<p>${esc(b.tagline)}</p>`:''}<small>PROPOSTA COMERCIAL</small><h2>${esc(b.headline||demo.title)}</h2>${b.welcome?`<p>${esc(b.welcome)}</p>`:''}<p>Orçamento #${esc(demo.number)} · ${esc(demo.clientName)}</p><div class="quote-web-card"><h3>Detalhes da Proposta</h3><p>${esc(demo.description||b.intro)}</p><h4>Serviços Incluídos</h4>${demo.items.map(x=>`<div>${esc(x.name)} <b>${money(x.quantity*x.price)}</b></div>`).join('')}<strong>Total: ${money(quoteTotal(demo))}</strong></div>${b.about||b.methodology||b.portfolio?`<div class="quote-web-card quote-agency-card">${b.about?`<h3>Sobre ${esc(b.agencyName||'nós')}</h3><p>${esc(b.about)}</p>`:''}${b.methodology?`<h3>Como trabalhamos</h3><p>${esc(b.methodology)}</p>`:''}${b.portfolio?`<h3>Portfólio e resultados</h3><p>${esc(b.portfolio)}</p>`:''}</div>`:''}${b.showReviews&&(b.reviews||[]).some(x=>x.name&&x.comment)?`<div class="quote-web-card quote-editor-public"><h3>Avaliações de Clientes</h3>${b.reviews.filter(x=>x.name&&x.comment).map(x=>`<div class="quote-review-preview">${x.photo?`<img src="${esc(x.photo)}" alt="">`:''}<div><b>${esc(x.name)}</b><span>${'★'.repeat(Math.min(5,Math.max(1,Number(x.rating)||5)))}</span><p>${esc(x.comment)}</p></div></div>`).join('')}</div>`:''}${b.showProjects&&(b.projects||[]).some(x=>x.title)?`<div class="quote-web-card quote-editor-public"><h3>Projetos do Portfólio</h3>${b.projects.filter(x=>x.title).slice(0,Math.min(6,Math.max(1,Number(b.maxProjects)||4))).map(x=>`<div class="quote-project-preview">${x.image?`<img src="${esc(x.image)}" alt="${esc(x.title)}">`:''}<b>${esc(x.title)}</b><small>${esc(x.client)}</small><p>${esc(x.description)}</p></div>`).join('')}</div>`:''}<button disabled>✓ ${esc(b.approvalLabel||'Aprovar Proposta')}</button><p>${esc(b.thanks)}</p></div>`}
function quotePdfSettings(){const p=quoteState.pdf,q=quoteState.items.find(x=>x.id===quoteState.previewId)||quoteState.items[0];return `<div class="quote-config-layout pdf"><div class="quote-config"><section class="quote-panel"><h3>Cabeçalho do PDF</h3><p>Personalize a logo e o banner exibidos no topo do PDF.</p><label>Logo do cabeçalho</label><div class="quote-upload-preview compact">${p.logo?`<img src="${p.logo}" alt="Logo do PDF">`:'Logo do perfil'}</div><label class="quote-upload-button">↑ Enviar logo<input type="file" data-quote-upload="pdf-logo" accept="image/png,image/jpeg,image/webp" hidden></label>${p.logo?'<button data-quote="remove-pdf-logo">Usar do perfil</button>':''}<hr><label>Banner / imagem do topo</label><label class="quote-upload-button">↑ Enviar banner (PNG/JPG)<input type="file" data-quote-upload="pdf-banner" accept="image/png,image/jpeg,image/webp" hidden></label>${p.banner?`<div class="quote-upload-preview"><img src="${p.banner}" alt="Banner do PDF"></div><button data-quote="remove-banner">Remover banner</button>`:''}</section><section class="quote-panel"><h3>Estilo visual</h3><label>Template<select data-quote-pdf="template"><option value="moderno" ${p.template==='moderno'?'selected':''}>Moderno — faixa escura com logo centralizado</option><option value="minimal" ${p.template==='minimal'?'selected':''}>Minimalista — cabeçalho limpo</option><option value="colorful" ${p.template==='colorful'?'selected':''}>Colorido — faixa na cor primária</option></select></label><div class="quote-two">${[['primary','Cor primária'],['accent','Cor de destaque'],['background','Cor de fundo'],['text','Cor do texto']].map(([key,label])=>`<label>${label}<input type="color" data-quote-pdf="${key}" value="${quoteHex(p[key],'#ffffff')}"></label>`).join('')}</div><label>Marca d’água<input data-quote-pdf="watermark" value="${esc(p.watermark)}"></label><label>Opacidade: <span id="opacity-value">${Number(p.opacity)||0}%</span><input type="range" min="0" max="40" data-quote-pdf="opacity" value="${Number(p.opacity)||0}"></label></section><section class="quote-panel"><h3>Textos personalizados</h3><label>Introdução<textarea rows="3" data-quote-pdf="intro">${esc(p.intro)}</textarea></label><label>Observações / termos<textarea rows="3" data-quote-pdf="terms">${esc(p.terms)}</textarea></label><label>Rodapé<textarea rows="2" data-quote-pdf="footer">${esc(p.footer)}</textarea></label></section><section class="quote-panel"><h3>Blocos exibidos</h3>${Object.entries({logo:'Logo no cabeçalho',description:'Descrição do orçamento',validity:'Validade',delivery:'Prazo de entrega',payment:'Condições de pagamento',contact:'Contato no rodapé'}).map(([key,title])=>`<label class="quote-toggle">${title}<input type="checkbox" data-quote-block="${key}" ${p.blocks[key]?'checked':''}></label>`).join('')}</section><section class="quote-panel"><h3>Termos e Condições</h3><p>Cadastre modelos para anexar aos orçamentos.</p><button data-quote="new-model">＋ Novo modelo</button>${p.models.map(m=>`<div class="quote-model"><b>${esc(m.title)} ${m.default?'<small>☆ Padrão</small>':''}</b><div><button data-quote="edit-model" data-id="${esc(m.id)}">Editar</button><button data-quote="delete-model" data-id="${esc(m.id)}">Excluir</button></div><p>${esc(m.body.slice(0,120))}</p></div>`).join('')}</section><button class="primary" data-quote="save-pdf">Salvar personalização</button></div><div class="quote-live"><p>PRÉVIA AO VIVO</p><select id="quote-preview-select" aria-label="Orçamento da prévia"><option value="">Exemplo</option>${quoteState.items.map(x=>`<option value="${esc(x.id)}" ${quoteState.previewId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div class="quote-pdf-preview">${quotePrintHTML(q||quoteDemo(),true)}</div><button data-quote="print" data-id="${esc(q?.id||'')}">⇩ Imprimir / salvar PDF</button></div></div>`}
function quoteDemo(){return {number:'PRÉVIA-001',title:'Projeto exemplo',clientName:'Cliente Exemplo',clientEmail:'cliente@exemplo.com',description:'Esta é uma prévia. Edite ao lado para ver as mudanças.',issued:quoteToday(),validity:'',items:[{name:'Serviço A',quantity:1,price:1500},{name:'Serviço B',quantity:2,price:800}],discount:0}}
function quotePrintHTML(q,embedded=false){const p=quoteState.pdf,subtotal=(q.items||[]).reduce((n,x)=>n+x.quantity*x.price,0),logo=p.logo||quoteState.brand.logo;return `<article class="quote-paper ${esc(p.template)}" style="--paper-primary:${quoteHex(p.primary,'#111111')};--paper-accent:${quoteHex(p.accent,'#ff633a')};--paper-bg:${quoteHex(p.background,'#ffffff')};--paper-text:${quoteHex(p.text,'#1a1a1a')}"><div class="quote-paper-head">${p.banner?`<img class="banner" src="${p.banner}" alt="Banner">`:''}${p.blocks.logo&&logo?`<img class="paper-logo" src="${logo}" alt="Logo">`:''}<h2>ORÇAMENTO</h2><small>${esc(q.number)}</small></div><div class="paper-content">${p.watermark?`<span class="paper-watermark" style="opacity:${(Number(p.opacity)||0)/100}">${esc(p.watermark)}</span>`:''}<div class="paper-meta"><div><b>CLIENTE</b><p>${esc(q.clientName)}<br>${esc(q.clientEmail)}</p></div><div><b>DETALHES</b><p>Data: ${formatDate(q.issued)}${p.blocks.validity&&q.validity?`<br>Validade: ${formatDate(q.validity)}`:''}</p></div></div><p>${esc(p.intro)}</p><h3>${esc(q.title)}</h3>${p.blocks.description&&q.description?`<p>${esc(q.description)}</p>`:''}<table><thead><tr><th>Serviço</th><th>Qtd</th><th>Valor Unit.</th><th>Total</th></tr></thead><tbody>${(q.items||[]).map(x=>`<tr><td>${esc(x.name)}<small>${esc(x.description||'')}</small></td><td>${x.quantity}</td><td>${money(x.price)}</td><td>${money(x.quantity*x.price)}</td></tr>`).join('')}</tbody></table><div class="paper-totals"><p>Subtotal: ${money(subtotal)}</p>${q.discount?`<p>Desconto: − ${money(q.discount)}</p>`:''}<strong>Total: ${money(quoteTotal(q))}</strong></div>${p.blocks.delivery&&q.delivery?`<p><b>Prazo de entrega:</b> ${esc(q.delivery)}</p>`:''}${p.blocks.payment&&q.payment?`<p><b>Condições de pagamento:</b> ${esc(q.payment)}</p>`:''}${q.terms||p.terms?`<p><b>Termos:</b> ${esc(q.terms||p.terms)}</p>`:''}<footer>${esc(p.footer)}${p.blocks.contact&&q.clientEmail?` · ${esc(q.clientEmail)}`:''}</footer></div></article>`}
function quoteModal(title,content,formId){document.querySelector('.quote-dialog')?.remove();const layer=document.createElement('div');layer.className='quote-dialog';layer.innerHTML=`<div class="quote-dialog-card" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2><button data-quote="close" aria-label="Fechar">×</button></header>${formId?`<form id="${formId}">${content}<div class="quote-dialog-actions"><button type="button" data-quote="close">Cancelar</button><button class="primary">Salvar</button></div></form>`:content}</div>`;document.body.append(layer);layer.querySelector('input,select,textarea')?.focus();return layer}
function quoteForm(id){const q=quoteState.items.find(x=>x.id===id);quoteState.editingId=id||null;const items=q?.items?.length?q.items:[{name:'',description:'',quantity:1,price:0}];quoteModal(q?'Editar orçamento':'Novo orçamento',`<div class="quote-form-grid"><label>Cliente<select name="clientId" id="quote-client"><option value="">Outro cliente</option>${clientsState.items.filter(c=>!c.archived).map(c=>`<option value="${esc(c.id)}" ${q?.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Nome do cliente<input name="clientName" required value="${esc(q?.clientName)}"></label></div><label>E-mail do cliente<input name="clientEmail" type="email" value="${esc(q?.clientEmail)}"></label><div class="quote-form-grid"><label>Título do orçamento *<input name="title" required maxlength="200" value="${esc(q?.title)}"></label><label>Número<input name="number" value="${esc(q?.number||'ORC-'+new Date().getFullYear()+'-'+String(quoteState.items.length+1).padStart(3,'0'))}"></label></div><label>Descrição do projeto<textarea name="description" rows="3">${esc(q?.description)}</textarea></label><h3>Serviços incluídos</h3><div id="quote-item-list">${items.map((x,i)=>quoteItemForm(x,i)).join('')}</div><button type="button" data-quote="add-item">＋ Adicionar serviço</button><div class="quote-form-grid"><label>Desconto (R$)<input name="discount" type="number" min="0" step="0.01" value="${Number(q?.discount)||0}"></label><label>Validade<input name="validity" type="date" value="${esc(q?.validity)}"></label></div><div class="quote-form-grid"><label>Prazo de entrega<input name="delivery" value="${esc(q?.delivery)}"></label><label>Condições de pagamento<input name="payment" value="${esc(q?.payment)}"></label></div><label>Termos específicos<textarea name="terms" rows="3">${esc(q?.terms||quoteState.pdf.models.find(m=>m.default)?.body||'')}</textarea></label>`, 'quote-form')}
function quoteItemForm(x,i){return `<div class="quote-form-item"><div class="quote-form-grid"><label>Serviço<input name="itemName" required value="${esc(x.name)}"></label><label>Descrição<input name="itemDescription" value="${esc(x.description)}"></label></div><div class="quote-form-grid"><label>Quantidade<input name="itemQuantity" type="number" required min="0.01" step="0.01" value="${Number(x.quantity)||1}"></label><label>Valor unitário (R$)<input name="itemPrice" type="number" required min="0" step="0.01" value="${Number(x.price)||0}"></label></div><button type="button" data-quote="remove-item" aria-label="Remover serviço">× Remover</button></div>`}
function quotePreview(id){const q=quoteState.items.find(x=>x.id===id);if(!q)return;quoteState.previewId=id;quoteModal('Prévia do orçamento',`<div class="quote-preview-modal">${quoteWebPreview(q,quoteState.brand)}</div><div class="quote-dialog-actions"><button data-quote="close">Fechar</button><button data-quote="pdf-preview" data-id="${esc(q.id)}">Ver PDF</button><button class="primary" data-quote="link" data-id="${esc(q.id)}">Gerar link de aprovação</button></div>`)}
function quoteDetails(id){const q=quoteState.items.find(x=>x.id===id);if(!q)return;quoteModal('Detalhes do orçamento',`<dl class="quote-details"><dt>Número</dt><dd>${esc(q.number)}</dd><dt>Cliente</dt><dd>${esc(q.clientName)} · ${esc(q.clientEmail)}</dd><dt>Status</dt><dd>${esc(q.status)}${q.approverName?' · '+esc(q.approverName)+' ('+esc(q.approverEmail)+')':''}</dd><dt>Total</dt><dd>${money(quoteTotal(q))}</dd><dt>Link</dt><dd>${q.remoteId?`<a target="_blank" rel="noopener" href="${quoteLink(q)}">${quoteLink(q)}</a>`:'Ainda não gerado'}</dd></dl><div class="quote-dialog-actions"><button data-quote="close">Fechar</button></div>`)}
async function quoteEnsureLink(q){if(!q.remoteId)await quoteRemote(q);return quoteLink(q)}
async function quoteCopy(q){const link=await quoteEnsureLink(q);await navigator.clipboard.writeText(link);toast('Link de aprovação copiado.')}
function quoteMail(q,attachment=false){const link=quoteLink(q);const subject=`Orçamento ${q.number} · ${q.title}`,body=attachment?`Olá, ${q.clientName}.\n\nSegue o orçamento ${q.number}. Abra o PDF pelo botão do CRM para anexá-lo a esta mensagem.\n\nPágina para aprovação: ${link}`:`Olá, ${q.clientName}.\n\nEnviamos sua proposta para análise e aprovação:\n${link}\n\nFicamos à disposição.`;location.href=`mailto:${encodeURIComponent(q.clientEmail||'')}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
function quotePrint(q){const page=quotePrintHTML(q||quoteDemo());const root=document.createElement('div');root.className='quote-print-root';root.innerHTML=page;document.body.append(root);window.print();setTimeout(()=>root.remove(),1200)}
async function quoteAction(action,id,b){const q=quoteState.items.find(x=>x.id===id);if(action==='tab'){quoteState.tab=b.dataset.tab;renderQuotes();return}if(action==='new'){quoteForm();return}if(action==='close'){document.querySelector('.quote-dialog')?.remove();return}if(action==='add-item'){document.querySelector('#quote-item-list')?.insertAdjacentHTML('beforeend',quoteItemForm({name:'',description:'',quantity:1,price:0},0));return}if(action==='remove-item'){const rows=document.querySelectorAll('.quote-form-item');if(rows.length>1)b.closest('.quote-form-item').remove();else toast('O orçamento precisa de um serviço.');return}if(action==='new-contract'){quoteContractForm();return}if(action==='refresh'){await quoteRefresh();toast('Status das propostas atualizado.');return}if(action==='archived'){quoteState.archived=!quoteState.archived;renderQuotes();return}if(action==='palette'){quoteState.brand.primary=b.dataset.primary;quoteState.brand.secondary=b.dataset.secondary;quotePersist();renderQuotes();return}if(action==='publish-brand'){const selected=quoteState.items.find(x=>x.id===quoteState.previewId)||quoteState.items[0];if(!selected){toast('Crie um orçamento antes de gerar a página.');return}try{await quoteRemote(selected);renderQuotes();toast('Página publicada. Abra o link para conferir a apresentação.')}catch(err){toast(err.message||'Não foi possível publicar a página.')}return}if(action==='save-brand'||action==='save-pdf'){quotePersist();toast('Personalização salva neste navegador. Atualize o link do orçamento para publicar a nova aparência.');return}if(action==='remove-logo'){quoteState.brand.logo='';quotePersist();renderQuotes();return}if(action==='remove-pdf-logo'||action==='remove-banner'){quoteState.pdf[action==='remove-banner'?'banner':'logo']='';quotePersist();renderQuotes();return}if(action==='new-model'||action==='edit-model'){quoteModelForm(id);return}if(action==='delete-model'){quoteState.pdf.models=quoteState.pdf.models.filter(m=>m.id!==id);quotePersist();renderQuotes();return}if(action==='print'){quotePrint(q);return}if(action==='contract-preview'){quoteContractPreview(id);return}if(action==='print-contract'){const c=quoteState.contracts.find(x=>x.id===id);if(c){const root=document.createElement('div');root.className='quote-print-root';root.innerHTML=`<article class="quote-paper"><div class="paper-content"><div class="quote-contract-document"><pre>${esc(contractText(c))}</pre></div></div></article>`;document.body.append(root);window.print();setTimeout(()=>root.remove(),1200)}return}if(action==='contract-delete'){quoteState.contracts=quoteState.contracts.filter(x=>x.id!==id);quotePersist();renderQuotes();return}if(!q)return;if(action==='menu'){quoteState.menuId=quoteState.menuId===id?null:id;renderQuotes();return}quoteState.menuId=null;if(action==='edit'){quoteForm(id);return}if(action==='details'){quoteDetails(id);return}if(action==='preview'){quotePreview(id);return}if(action==='pdf-preview'){document.querySelector('.quote-dialog')?.remove();quoteState.previewId=id;quoteState.tab='PDF';renderQuotes();return}if(action==='duplicate'){const clone={...structuredClone(q),id:crypto.randomUUID(),number:q.number+'-CÓPIA',status:'rascunho',remoteId:null,editToken:null,approvedAt:null};quoteState.items.unshift(clone);quotePersist();renderQuotes();toast('Orçamento duplicado.');return}if(action==='archive'){q.archived=!q.archived;quotePersist();renderQuotes();return}if(action==='delete'){if(confirm('Excluir este orçamento do CRM? O link já compartilhado continuará acessível ao cliente.')){quoteState.items=quoteState.items.filter(x=>x.id!==id);quotePersist();renderQuotes()}return}if(action==='approve'){if(!confirm('Registrar aprovação manual deste orçamento?'))return;q.status='aprovado';q.approvedAt=new Date().toISOString();q.approverName='Aprovação manual';quoteSyncClient(q);quoteTrack(q,'Orçamento aprovado manualmente');quotePersist();renderQuotes();return}if(action==='charge'){const c=quoteClient(q);if(!c){toast('Vincule um cliente para registrar a cobrança.');return}if(q.charge){toast('Já existe uma conta a receber deste orçamento.');return}q.charge={id:crypto.randomUUID(),description:q.title,amount:quoteTotal(q),status:'pendente',due:q.validity||quoteToday()};quoteSyncClient(q);quotePersist();quoteTrack(q,'Conta a receber criada');toast('Conta a receber cadastrada no cliente. Nenhum pagamento foi solicitado.');return}if(action==='contract'){quoteContractForm(q);return}if(action==='complete'){q.status='enviado';quoteTrack(q,'Orçamento finalizado sem e-mail');quotePersist();renderQuotes();return}if(action==='send'){try{await quoteEnsureLink(q);quoteMail(q);if(confirm('O e-mail foi enviado pelo seu aplicativo de e-mail?')){q.status='enviado';quoteTrack(q,'Envio de orçamento confirmado');quotePersist()}renderQuotes()}catch(err){toast(err.message)}return}if(['copy','link','share','email','pdf-email'].includes(action)){try{if(q.remoteId&&q.status!=='aprovado'&&(action==='link'||action==='email'||action==='share'))await quoteRemote(q);await quoteEnsureLink(q);if(action==='email'||action==='pdf-email'){quoteMail(q,action==='pdf-email');if(confirm('O e-mail foi enviado pelo seu aplicativo de e-mail?')){q.status='enviado';quoteTrack(q,'Envio de orçamento confirmado')}}else if(action==='share'&&navigator.share){await navigator.share({title:q.title,url:quoteLink(q)})}else await quoteCopy(q);quotePersist();renderQuotes()}catch(err){toast(err.message||'Não foi possível compartilhar.')}return}}
function quoteContractForm(q){const layer=quoteModal('Novo contrato',`<label>Cliente<input name="clientName" required value="${esc(q?.clientName)}"></label><label>Projeto<input name="title" required value="${esc(q?.title)}"></label><label>Valor (R$)<input name="amount" type="number" min="0" step="0.01" required value="${esc(q?quoteTotal(q):0)}"></label><label>Cláusulas<textarea name="terms" rows="8" required>${esc(q?.terms||quoteState.pdf.models.find(x=>x.default)?.body||'')}</textarea></label>`, 'quote-contract-form');layer.dataset.quoteId=q?.id||''}
function quoteContractPreview(id){const c=quoteState.contracts.find(x=>x.id===id);if(!c)return;quoteModal('Contrato · '+c.clientName,`<div class="quote-contract-document"><h2>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h2><p><b>Contratante:</b> ${esc(c.clientName)}</p><p><b>Objeto:</b> ${esc(c.title)}</p><p><b>Valor:</b> ${money(c.amount)}</p><p>${esc(c.terms)}</p><p>Data: ${formatDate(c.date)}</p></div><div class="quote-dialog-actions"><button data-quote="close">Fechar</button><button data-quote="print-contract" data-id="${esc(id)}">Imprimir / salvar PDF</button></div>`)}
function quoteModelForm(id){const m=quoteState.pdf.models.find(x=>x.id===id);const layer=quoteModal(m?'Editar modelo':'Novo modelo',`<label>Nome do modelo<input name="title" required value="${esc(m?.title)}"></label><label>Termos<textarea name="body" rows="8" required>${esc(m?.body)}</textarea></label><label class="quote-toggle">Usar como padrão<input type="checkbox" name="default" ${m?.default?'checked':''}></label>`, 'quote-model-form');layer.dataset.modelId=id||''}
function quoteSave(form){const f=new FormData(form),id=quoteState.editingId,old=quoteState.items.find(q=>q.id===id),names=f.getAll('itemName');const items=names.map((name,i)=>({name:String(name).trim(),description:String(f.getAll('itemDescription')[i]||''),quantity:Number(f.getAll('itemQuantity')[i])||1,price:Number(f.getAll('itemPrice')[i])||0}));const clientId=String(f.get('clientId')||''),linked=clientsState.items.find(c=>c.id===clientId);const data={clientId,clientName:String(f.get('clientName')||'').trim(),clientEmail:String(f.get('clientEmail')||'').trim(),title:String(f.get('title')||'').trim(),number:String(f.get('number')||'').trim(),description:String(f.get('description')||'').trim(),discount:Number(f.get('discount'))||0,validity:String(f.get('validity')||''),delivery:String(f.get('delivery')||''),payment:String(f.get('payment')||''),terms:String(f.get('terms')||''),items};if(!data.title||!data.clientName||items.some(x=>!x.name)){toast('Preencha cliente, título e todos os serviços.');return}if(old){Object.assign(old,data);quoteTrack(old,'Orçamento editado')}else{const q={...data,id:crypto.randomUUID(),status:'rascunho',issued:quoteToday(),archived:false,remoteId:null,editToken:null};quoteState.items.unshift(q);quoteTrack(q,'Orçamento criado')}quotePersist();document.querySelector('.quote-dialog')?.remove();renderQuotes();toast('Orçamento salvo.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-quote]');if(!b)return;quoteAction(b.dataset.quote,b.dataset.id,b)});
document.addEventListener('submit',e=>{if(e.target.id==='quote-form'){e.preventDefault();quoteSave(e.target)}else if(e.target.id==='quote-contract-form'){e.preventDefault();const f=new FormData(e.target),q=quoteState.items.find(x=>x.id===e.target.closest('.quote-dialog').dataset.quoteId);quoteState.contracts.unshift({id:crypto.randomUUID(),quoteId:q?.id,clientName:String(f.get('clientName')),title:String(f.get('title')),amount:Number(f.get('amount'))||0,terms:String(f.get('terms')),status:'rascunho',date:quoteToday()});quotePersist();document.querySelector('.quote-dialog')?.remove();quoteState.tab='Contratos';renderQuotes();toast('Contrato registrado.')}else if(e.target.id==='quote-model-form'){e.preventDefault();const f=new FormData(e.target),id=e.target.closest('.quote-dialog').dataset.modelId;let m=quoteState.pdf.models.find(x=>x.id===id);if(m)Object.assign(m,{title:String(f.get('title')),body:String(f.get('body')),default:f.has('default')});else{m={id:crypto.randomUUID(),title:String(f.get('title')),body:String(f.get('body')),default:f.has('default')};quoteState.pdf.models.push(m)}if(m.default)quoteState.pdf.models.forEach(x=>{if(x!==m)x.default=false});quotePersist();document.querySelector('.quote-dialog')?.remove();renderQuotes()}});
document.addEventListener('input',e=>{const x=e.target;if(x.id==='quote-search'){quoteState.query=x.value;const pos=x.selectionStart;renderQuotes();const input=document.querySelector('#quote-search');input.focus();input.setSelectionRange(pos,pos)}if(x.dataset.quoteBrand){quoteState.brand[x.dataset.quoteBrand]=x.value;quotePersist();const preview=document.querySelector('.quote-live .quote-web-preview');if(preview){const q=quoteState.items.find(q=>q.id===quoteState.previewId)||quoteState.items[0];preview.outerHTML=quoteWebPreview(q,quoteState.brand)}}if(x.dataset.quotePdf){quoteState.pdf[x.dataset.quotePdf]=x.value;quotePersist();if(x.dataset.quotePdf==='opacity')document.querySelector('#opacity-value').textContent=x.value+'%';if(x.type==='color'||x.type==='range'){const page=document.querySelector('.quote-pdf-preview');if(page)page.innerHTML=quotePrintHTML(quoteState.items.find(q=>q.id===quoteState.previewId)||quoteDemo(),true)}}});
document.addEventListener('change',async e=>{const x=e.target;if(x.id==='quote-status'){quoteState.status=x.value;renderQuotes()}if(x.id==='quote-client'){const c=clientsState.items.find(c=>c.id===x.value),form=x.closest('form');if(c){form.elements.namedItem('clientName').value=c.name;form.elements.namedItem('clientEmail').value=c.email}}if(x.id==='quote-preview-select'||x.id==='quote-brand-preview-select'){quoteState.previewId=x.value;renderQuotes()}if(x.dataset.quoteBlock){quoteState.pdf.blocks[x.dataset.quoteBlock]=x.checked;quotePersist();document.querySelector('.quote-pdf-preview').innerHTML=quotePrintHTML(quoteState.items.find(q=>q.id===quoteState.previewId)||quoteDemo(),true)}if(x.dataset.quoteUpload){const file=x.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5000000){toast('Use PNG, JPG ou WebP com até 5 MB.');x.value='';return}try{const data=await quoteImageData(file);if(x.dataset.quoteUpload.startsWith('pdf-'))quoteState.pdf[x.dataset.quoteUpload.slice(4)]=data;else quoteState.brand[x.dataset.quoteUpload]=data;quotePersist();renderQuotes();toast('Imagem carregada e exibida na prévia.')}catch(err){toast(err.message||'Não foi possível carregar a imagem.')}}});
async function quoteImageData(file){const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),limit=1100,scale=Math.min(1,limit/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let data=canvas.toDataURL('image/webp',.82);if(data.length>430000)data=canvas.toDataURL('image/webp',.55);if(data.length>430000)throw Error('Imagem muito grande. Escolha um arquivo menor.');return data}

document.addEventListener('click',e=>{const b=e.target.closest('[data-quote-editor-add],[data-quote-editor-remove],[data-quote-editor-clear]');if(!b)return;const brand=quoteState.brand,kind=b.dataset.quoteEditorAdd||b.dataset.quoteEditorRemove||b.dataset.quoteEditorClear;if(!['reviews','projects'].includes(kind))return;brand[kind]=Array.isArray(brand[kind])?brand[kind]:[];if(b.dataset.quoteEditorAdd){if(brand[kind].length>=6){toast('Limite de 6 itens.');return}brand[kind].push(kind==='reviews'?{name:'',rating:5,comment:'',photo:''}:{title:'',client:'',description:'',url:'',image:''})}else if(b.dataset.quoteEditorRemove){brand[kind].splice(Number(b.dataset.index),1)}else{const item=brand[kind][Number(b.dataset.index)];if(item)item[kind==='reviews'?'photo':'image']=''}quotePersist();const open=[...document.querySelectorAll('.quote-editor-panel details')].map(x=>x.open);renderQuotes();document.querySelectorAll('.quote-editor-panel details').forEach((x,i)=>x.open=open[i])});
document.addEventListener('input',e=>{const x=e.target,brand=quoteState.brand;if(x.dataset.quoteEditorField){const item=brand[x.dataset.kind]?.[Number(x.dataset.index)];if(!item)return;item[x.dataset.quoteEditorField]=x.dataset.quoteEditorField==='rating'?Math.min(5,Math.max(1,Number(x.value)||1)):x.value;quotePersist();quoteRefreshWebPreview()}if(x.dataset.quoteEditorSetting){brand[x.dataset.quoteEditorSetting]=Math.min(6,Math.max(1,Number(x.value)||4));quotePersist();quoteRefreshWebPreview()}});
document.addEventListener('change',async e=>{const x=e.target,brand=quoteState.brand;if(x.dataset.quoteEditorToggle){brand[x.dataset.quoteEditorToggle]=x.checked;quotePersist();quoteRefreshWebPreview()}if(x.dataset.quoteEditorImage){const kind=x.dataset.quoteEditorImage,item=brand[kind]?.[Number(x.dataset.index)],file=x.files?.[0];if(!item||!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5000000){toast('Use PNG, JPG ou WebP com até 5 MB.');return}try{item[kind==='reviews'?'photo':'image']=await quoteSmallImageData(file);quotePersist();const open=[...document.querySelectorAll('.quote-editor-panel details')].map(y=>y.open);renderQuotes();document.querySelectorAll('.quote-editor-panel details').forEach((y,i)=>y.open=open[i])}catch(err){toast(err.message||'Não foi possível carregar a imagem.')}}});
async function quoteSmallImageData(file){const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,420/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();for(const quality of [.7,.5,.35]){const data=canvas.toDataURL('image/webp',quality);if(data.length<45000)return data}throw Error('Imagem muito grande. Escolha uma imagem menor.')}
